     N'NET_PROFIT, REVENUE', N'هامش صافي ربح جيد: {v}%', N'Good net margin: {v}%', N'هامش صافي الربح {v}%', N'Net margin is {v}%'),
    ('CFO_TO_EBITDA', N'تحويل الأرباح إلى نقد', N'Cash conversion of EBITDA', 'QUANTITATIVE', 'PERCENT', 'HIGHER_BETTER',
     N'صافي التدفق التشغيلي ÷ EBITDA × 100: جودة الأرباح. يلزم قائمة تدفقات؛ EBITDA غير موجب مع تدفق سالب: حرجة',
     N'OP_CASH_FLOW, OPERATING_PROFIT, DEPR_AMORT', N'أرباح تتحول إلى نقد: {v}% من EBITDA', N'Earnings convert to cash: {v}% of EBITDA', N'التدفق التشغيلي {v}% من EBITDA', N'Operating cash flow is {v}% of EBITDA'),
    ('PAYOUT_RATIO', N'نسبة توزيع الأرباح', N'Dividend payout', 'QUANTITATIVE', 'PERCENT', 'LOWER_BETTER',
