     N'DIVIDENDS, NET_PROFIT', N'توزيعات متحفظة: {v}% من الربح', N'Conservative dividends: {v}% of profit', N'التوزيعات {v}% من صافي الربح', N'Dividends are {v}% of net profit'),
    ('CONTINGENT_TO_TNW', N'الالتزامات المحتملة إلى صافي الثروة الملموسة المعدَّلة', N'Contingent liabilities / adjusted TNW', 'QUANTITATIVE', 'RATIO', 'LOWER_BETTER',
     N'(الاعتمادات المستندية القائمة + خطابات الضمان الحسنة التنفيذ + خطابات الضمان المالية + الكفالات المقدَّمة للغير) ÷ صافي الثروة الملموسة المعدَّلة، بالقيمة الإجمالية. صافي الثروة الملموسة المعدَّلة = إجمالي حقوق الملكية + قروض الشركاء المساندة − الأصول غير الملموسة − المستحق من أطراف ذات علاقة − احتياطي إعادة التقييم. صافي ثروة غير موجب مع التزامات: أسوأ درجة',
     N'LC_OUTSTANDING, LG_PERFORMANCE, LG_FINANCIAL, GUARANTEES_GIVEN, صافي الثروة الملموسة المعدَّلة', N'التزامات محتملة محدودة: {v} مرة من صافي الثروة ({g})', N'Limited contingent liabilities: {v}x net worth ({g})', N'الالتزامات المحتملة {v} مرة من صافي الثروة الملموسة ({g})', N'Contingent liabilities are {v}x tangible net worth ({g})'),
    ('ST_DEBT_TO_TRADE_ASSETS', N'تمويل التجارة قصير الأجل إلى الذمم والمخزون', N'Short-term trade finance / receivables and inventory', 'QUANTITATIVE', 'PERCENT', 'LOWER_BETTER',
     N'(القروض قصيرة الأجل + القبولات البنكية) ÷ (الذمم المدينة + المخزون) × 100: هل تغطي الأصول ذاتية التسييل خطوط التجارة. لا أصول تجارية مع دين: حرجة',
     N'ST_LOANS, BANK_ACCEPTANCES, AR, INVENTORY', N'خطوط التجارة مغطاة بالذمم والمخزون: {v}%', N'Trade lines covered by receivables and inventory: {v}%', N'خطوط التجارة {v}% من الذمم والمخزون', N'Trade lines are {v}% of receivables and inventory'),
    ('EOSB_TO_TNW', N'مكافأة نهاية الخدمة إلى صافي الثروة الملموسة', N'End-of-service benefits / adjusted TNW', 'QUANTITATIVE', 'PERCENT', 'LOWER_BETTER',
     N'مخصص مكافأة نهاية الخدمة غير الممول ÷ صافي الثروة الملموسة المعدَّلة × 100: التزام شبيه بالدين. صافي ثروة غير موجب مع مخصص: حرجة',
     N'EOSB, صافي الثروة الملموسة المعدَّلة', N'مخصص نهاية الخدمة محدود: {v}%', N'Limited end-of-service provision: {v}%', N'مخصص نهاية الخدمة {v}% من صافي الثروة الملموسة', N'End-of-service provision is {v}% of tangible net worth'),
    ('ZAKAT_DISPUTED_TO_TNW', N'الزكاة المستحقة والمتنازع عليها إلى صافي الثروة', N'Zakat payable and disputed / adjusted TNW', 'QUANTITATIVE', 'PERCENT', 'LOWER_BETTER',
     N'ربوط الزكاة والضريبة المتنازع عليها وغير المخصصة ÷ صافي الثروة الملموسة المعدَّلة × 100. صافي ثروة غير موجب مع ربوط: حرجة',
     N'ZAKAT_DISPUTED, صافي الثروة الملموسة المعدَّلة', N'لا ربوط زكوية جوهرية متنازع عليها: {v}%', N'No material disputed zakat assessments: {v}%', N'ربوط الزكاة المتنازع عليها {v}% من صافي الثروة الملموسة', N'Disputed zakat assessments are {v}% of tangible net worth'),
    ('DUE_TO_RELATED_TO_TNW', N'المستحق لأطراف ذات علاقة إلى صافي الثروة', N'Due to related parties / adjusted TNW', 'QUANTITATIVE', 'PERCENT', 'LOWER_BETTER',
     N'المستحق لأطراف ذات علاقة غير المساند ÷ صافي الثروة الملموسة المعدَّلة × 100: تمويل قد يُسحب قبل البنوك. صافي ثروة غير موجب مع مستحق: حرجة',
     N'DUE_TO_RELATED, صافي الثروة الملموسة المعدَّلة', N'اعتماد محدود على تمويل الأطراف ذات العلاقة: {v}%', N'Limited reliance on related-party funding: {v}%', N'المستحق لأطراف ذات علاقة {v}% من صافي الثروة الملموسة', N'Due to related parties is {v}% of tangible net worth'),
    ('OTHER_CA_SHARE', N'الأصول المتداولة الأخرى إلى الأصول المتداولة', N'Other current assets / current assets', 'QUANTITATIVE', 'PERCENT', 'LOWER_BETTER',
     N'الأصول المتداولة الأخرى ÷ إجمالي الأصول المتداولة × 100: قد تخفي دفعات مقدمة لأطراف ذات علاقة. لا أصول متداولة: لا يُحسب',
     N'OTHER_CA, TOTAL_CA', N'الأصول المتداولة مفصّلة: الأخرى {v}%', N'Current assets well itemised: other {v}%', N'الأصول المتداولة الأخرى {v}% من المتداولة', N'Other current assets are {v}% of current assets'),
    ('CONTRACT_ASSETS_TO_REVENUE', N'أصول العقود والمحتجزات إلى الإيرادات', N'Contract assets and retentions / revenue', 'QUANTITATIVE', 'PERCENT', 'LOWER_BETTER',
     N'أصول العقود (أعمال منجزة غير مفوترة) والمحتجزات ÷ الإيرادات السنوية × 100. إيرادات غير موجبة: لا يُحسب',
     N'CONTRACT_ASSETS, REVENUE', N'أصول عقود محدودة: {v}% من الإيرادات', N'Limited contract assets: {v}% of revenue', N'أصول العقود والمحتجزات {v}% من الإيرادات', N'Contract assets and retentions are {v}% of revenue'),
    ('GUARANTEES_TO_TNW', N'الكفالات المقدَّمة للغير إلى صافي الثروة', N'Guarantees given / adjusted TNW', 'QUANTITATIVE', 'PERCENT', 'LOWER_BETTER',
     N'الكفالات والضمانات المقدَّمة لالتزامات أطراف أخرى (غالبًا ذات علاقة) ÷ صافي الثروة الملموسة المعدَّلة × 100. صافي ثروة غير موجب مع كفالات: حرجة',
     N'GUARANTEES_GIVEN, صافي الثروة الملموسة المعدَّلة', N'لا كفالات جوهرية للغير: {v}%', N'No material guarantees given: {v}%', N'الكفالات المقدَّمة للغير {v}% من صافي الثروة الملموسة', N'Guarantees given are {v}% of tangible net worth')
) AS s (Code, NameAr, NameEn, Kind, Unit, Direction, DefinitionAr, InputsText, StrengthTextAr, StrengthTextEn, WeaknessTextAr, WeaknessTextEn)
   ON d.Code = s.Code
WHEN NOT MATCHED THEN
    INSERT (Code, NameAr, NameEn, Kind, Unit, Direction, DefinitionAr, InputsText, StrengthTextAr, StrengthTextEn, WeaknessTextAr, WeaknessTextEn)
    VALUES (s.Code, s.NameAr, s.NameEn, s.Kind, s.Unit, s.Direction, s.DefinitionAr, s.InputsText, s.StrengthTextAr, s.StrengthTextEn, s.WeaknessTextAr, s.WeaknessTextEn);
GO
-- GENERAL_CORPORATE version 1: General corporates: industry and services
IF NOT EXISTS (SELECT 1 FROM fin.Scorecard WHERE Code = 'GENERAL_CORPORATE' AND VersionNo = 1)
    INSERT fin.Scorecard (Code, VersionNo, NameAr, NameEn, SectorNoteAr, CurrencyId, AmountUnit, MinCoveragePct, QualitativeBoundNotches,
                          SupportMaxAgeMonths, Status, DisclaimerAr, DisclaimerEn)
    SELECT 'GENERAL_CORPORATE', 1, N'الشركات العامة: الصناعة والخدمات', N'General corporates: industry and services',
           N'الشركات الصناعية والخدمية وما لا يندرج في القطاعين الآخرين؛ البطاقة الافتراضية',
           cu.CurrencyId, 1000000, 85, 3, 12, 'DRAFT',
           N'تقييم داخلي يعتمد سلّم موديز (Moody''s) للتصنيف طويل الأجل وطريقة بطاقات التقييم المنشورة: درجة لكل مقياس على خط مستمر ووزن لكل عامل؛ والحدود معايرة بخبرة المحلل للسوق السعودية. ليس تصنيفًا صادرًا عن موديز ولا عن أي وكالة، ولا يحل محل التصنيف الداخلي للبنك.',
           N'An internal assessment on Moody''s long-term rating scale and its published scorecard approach (a score per metric on a linear continuum, a weight per factor); the thresholds are calibrated by expert judgment for the Saudi market. It is not a rating issued by Moody''s or any agency, and it does not replace a bank''s internal rating.'
    FROM ref.Currency AS cu WHERE cu.Code = 'SAR';
MERGE fin.ScorecardMetric AS d
USING (SELECT sc.ScorecardId, m.CreditMetricId, v.FactorCode, v.Weight, v.B0, v.B1, v.B2, v.B3, v.B4, v.B5, v.B6, v.B7, v.B8, v.SortOrder
       FROM (VALUES
        ('REVENUE_SIZE', 'SCALE', 15, 150000, 75000, 30000, 10000, 3000, 750, 100, 20, 2, 1),
        ('EBITDA_MARGIN', 'PROFITABILITY', 7.5, 45, 30, 22, 15, 10, 6, 3, 0, -10, 2),
        ('ROA', 'PROFITABILITY', 2.5, 20, 12, 8, 5, 3, 1.5, 0, -3, -10, 3),
        ('DEBT_TO_EBITDA', 'LEVERAGE', 12.5, 0, 0.5, 1.5, 2.5, 3.5, 4.5, 6, 8, 12, 4),
        ('TL_TO_TNW', 'LEVERAGE', 10, 0, 0.25, 0.6, 1, 1.75, 2.75, 4, 6, 10, 5),
        ('EBITDA_TO_INTEREST', 'COVERAGE', 5, 40, 20, 12, 7, 4, 2.5, 1.5, 1, 0, 6),
        ('DSCR', 'COVERAGE', 7.5, 6, 4, 2.75, 2, 1.5, 1.25, 1, 0.8, 0, 7),
        ('CFO_TO_DEBT', 'CASH_FLOW', 7.5, 150, 80, 50, 35, 20, 10, 5, 0, -20, 8),
        ('CURRENT_RATIO', 'LIQUIDITY', 2.5, 4, 3, 2.2, 1.6, 1.25, 1, 0.8, 0.6, 0.3, 9),
        ('CASH_CYCLE', 'LIQUIDITY', 5, -30, 0, 30, 60, 90, 120, 180, 270, 365, 10),
        ('BUSINESS_PROFILE', 'QUALITATIVE', 15, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 11),
        ('FINANCIAL_POLICY', 'QUALITATIVE', 10, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12)
            ) AS v (MetricCode, FactorCode, Weight, B0, B1, B2, B3, B4, B5, B6, B7, B8, SortOrder)
       JOIN fin.Scorecard AS sc ON sc.Code = 'GENERAL_CORPORATE' AND sc.VersionNo = 1 AND sc.Status = 'DRAFT'
       JOIN fin.CreditMetric AS m ON m.Code = v.MetricCode) AS s
   ON d.ScorecardId = s.ScorecardId AND d.MetricId = s.CreditMetricId
WHEN NOT MATCHED THEN
    INSERT (ScorecardId, MetricId, FactorCode, Weight, B0, B1, B2, B3, B4, B5, B6, B7, B8, SortOrder)
    VALUES (s.ScorecardId, s.CreditMetricId, s.FactorCode, s.Weight, s.B0, s.B1, s.B2, s.B3, s.B4, s.B5, s.B6, s.B7, s.B8, s.SortOrder);
MERGE fin.ScorecardItemRule AS d
USING (SELECT sc.ScorecardId, m.CreditMetricId, v.LineCode, v.T1, v.T2, v.T3, v.T4, v.ReportStrength, v.SortOrder
       FROM (VALUES
        ('CASH_TO_ST_DEBT', 'CASH', 0.75, 0.4, 0.2, 0.1, 1, 1),
        ('DSO', 'AR', 60, 90, 120, 180, 1, 2),
        ('DIO', 'INVENTORY', 60, 90, 150, 240, 1, 3),
        ('DPO', 'AP', 60, 90, 120, 180, 0, 4),
        ('RELATED_TO_TNW', 'DUE_FROM_RELATED', 5, 15, 30, 50, 1, 5),
        ('INTANGIBLES_TO_EQUITY', 'INTANGIBLES', 10, 25, 50, 75, 0, 6),
        ('NWC_TO_ASSETS', 'TOTAL_CA', 15, 5, 0, -10, 1, 7),
        ('ST_DEBT_SHARE', 'ST_LOANS', 40, 60, 80, 95, 1, 8),
        ('CFO_TO_CPLTD', 'CURRENT_PORTION_LTD', 2, 1.25, 1, 0.5, 1, 9),
        ('ACC_LOSS_TO_CAPITAL', 'RETAINED_EARNINGS', 0, 20, 35, 50, 0, 10),
        ('EQUITY_RATIO', 'TOTAL_EQUITY', 50, 35, 20, 10, 1, 11),
        ('REVENUE_GROWTH', 'REVENUE', 5, 0, -10, -25, 1, 12),
        ('GROSS_MARGIN_CHANGE', 'GROSS_PROFIT', 0, -2, -5, -10, 0, 13),
        ('NET_MARGIN', 'NET_PROFIT', 10, 5, 2, 0, 1, 14),
        ('CFO_TO_EBITDA', 'OP_CASH_FLOW', 80, 60, 40, 0, 1, 15),
        ('PAYOUT_RATIO', 'DIVIDENDS', 30, 50, 75, 100, 1, 16),
        ('CONTINGENT_TO_TNW', 'LG_PERFORMANCE', 0.5, 1, 2, 3, 0, 17),
        ('EOSB_TO_TNW', 'EOSB', 10, 20, 35, 50, 0, 18),
        ('ZAKAT_DISPUTED_TO_TNW', 'ZAKAT_DISPUTED', 2, 5, 10, 20, 0, 19),
        ('DUE_TO_RELATED_TO_TNW', 'DUE_TO_RELATED', 10, 25, 50, 100, 0, 20),
        ('OTHER_CA_SHARE', 'OTHER_CA', 15, 25, 40, 60, 0, 21),
        ('CONTRACT_ASSETS_TO_REVENUE', 'CONTRACT_ASSETS', 15, 25, 40, 60, 0, 22),
        ('GUARANTEES_TO_TNW', 'GUARANTEES_GIVEN', 25, 50, 100, 150, 0, 23)
            ) AS v (MetricCode, LineCode, T1, T2, T3, T4, ReportStrength, SortOrder)
       JOIN fin.Scorecard AS sc ON sc.Code = 'GENERAL_CORPORATE' AND sc.VersionNo = 1 AND sc.Status = 'DRAFT'
       JOIN fin.CreditMetric AS m ON m.Code = v.MetricCode) AS s
   ON d.ScorecardId = s.ScorecardId AND d.MetricId = s.CreditMetricId
WHEN NOT MATCHED THEN
    INSERT (ScorecardId, MetricId, LineCode, T1, T2, T3, T4, ReportStrength, SortOrder)
    VALUES (s.ScorecardId, s.CreditMetricId, s.LineCode, s.T1, s.T2, s.T3, s.T4, s.ReportStrength, s.SortOrder);
MERGE fin.ScorecardAdjustment AS d
USING (SELECT sc.ScorecardId, v.RuleCode, v.Stage, v.Notches, g.RatingGradeId AS CapGradeId, v.ParamValue, v.ShowWhen, v.NameAr, v.TextAr, v.TextEn
       FROM (VALUES
        ('AUDIT_QUALIFIED', 'NOTCH', -1, NULL, NULL, 'ALWAYS', N'رأي المراجع متحفظ',
     N'رأي المراجع متحفظ: تنزيل درجة واحدة',
     N'Qualified audit opinion: one notch down'),
        ('UNAUDITED_ANNUAL', 'NOTCH', -1, NULL, NULL, 'ALWAYS', N'قائمة سنوية غير مدققة',
     N'قائمة سنوية إدارية غير مدققة: تنزيل درجة واحدة',
     N'Unaudited (management) annual statement: one notch down'),
        ('STALE_STATEMENT', 'NOTCH', -1, NULL, 15, 'ALWAYS', N'قائمة قديمة',
     N'مضى على نهاية فترة القائمة أكثر من {p} شهرًا: تنزيل درجة واحدة',
     N'The statement''s period ended more than {p} months ago: one notch down'),
        ('INCOMPLETE_STATEMENT', 'NOTCH', -1, NULL, NULL, 'ALWAYS', N'لا قائمة تدفقات نقدية',
     N'لم تُقدَّم قائمة التدفقات النقدية: تنزيل درجة واحدة، فلا يكسب حجبُها درجة',
     N'No cash flow statement was given: one notch down, so leaving it out gains nothing'),
        ('RESTATEMENT', 'NOTCH', -1, NULL, 5, 'ALWAYS', N'إعادة عرض جوهرية',
     N'أعادت القائمة عرض صافي الربح أو حقوق الملكية بأكثر من {p}% عن الإصدار السابق: تنزيل درجة واحدة',
     N'The statement restated net profit or equity by more than {p}% of the earlier version: one notch down'),
        ('HALF_CAPITAL_LOST_CURED', 'NOTCH', -1, NULL, 50, 'ALWAYS', N'خسائر بلغت نصف رأس المال وعولجت',
     N'الخسائر المتراكمة بلغت {p}% من رأس المال أو أكثر، وتغطيها حقوق الملكية مع قروض الشركاء المساندة: تنزيل درجة واحدة',
     N'Accumulated losses reach {p}% of share capital, covered by equity and subordinated shareholder loans: one notch down'),
        ('RELATED_PARTY_EXPOSURE', 'NOTCH', -1, NULL, 50, 'ALWAYS', N'تعرّض للأطراف ذات العلاقة',
     N'المستحق من الأطراف ذات العلاقة والكفالات المقدَّمة لها تتجاوز {p}% من صافي الثروة الملموسة المعدَّلة: تنزيل درجة واحدة',
     N'Amounts due from related parties and guarantees given exceed {p}% of adjusted tangible net worth: one notch down'),
        ('HOLDCO_STANDALONE', 'NOTCH', -1, NULL, NULL, 'ALWAYS', N'قائمة منفردة لقابضة',
